import os,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
import numpy as np
A=np.array(G['Demo pair 2 input']); O=np.array(G['Demo pair 2 output'])
n=A.shape[0]
names=['id','T','flr','fud','r90','r180','r270','at']
cands=[A, A.T, np.fliplr(A), np.flipud(A), np.rot90(A), np.rot90(A,2), np.rot90(A,3), np.rot90(np.fliplr(A))]
for i in range(2):
 for j in range(2):
  b=O[i*n:(i+1)*n, j*n:(j+1)*n]
  for nm,c in zip(names,cands):
   if np.array_equal(b,c): print(i,j,nm)
